from concurrent.futures import ThreadPoolExecutor
import os
from pathlib import Path
import runpy
import shutil
import sys
import uuid


def fail(message):
    print(message, file=sys.stderr)
    raise SystemExit(2)


def digest_tree(root, plugin):
    excluded = {\x22hooks/codex.json\x22}
    if plugin == \x22machine\x22:
        excluded.add(\x22catalog/catalog.json\x22)
    files = []
    directories = [(root, \x22\x22)]
    while directories:
        directory, prefix = directories.pop()
        with os.scandir(directory) as entries:
            for entry in entries:
                relative = prefix + entry.name
                if entry.is_symlink():
                    fail(\x22Codex hook package contains a symbolic link\x22)
                if entry.is_dir(follow_symlinks=False):
                    directories.append((entry.path, relative + \x22/\x22))
                elif entry.is_file(follow_symlinks=False):
                    files.append((relative, entry.path))
                else:
                    fail(\x22Codex hook package contains an unsupported entry\x22)
    files = [(relative, Path(path)) for relative, path in sorted(files) if relative not in excluded]
    digest = hashlib.sha256()
    if files:
        with ThreadPoolExecutor(max_workers=min(16, len(files))) as reader:
            for start in range(0, len(files), 16):
                batch = files[start:start + 16]
                for (relative, _), content in zip(batch, reader.map(Path.read_bytes, [path for _, path in batch])):
                    try:
                        text = content.decode(\x22utf-8\x22)
                    except UnicodeDecodeError:
                        pass
                    else:
                        content = text.replace(\x22\r\n\x22, \x22\n\x22).replace(\x22\r\x22, \x22\n\x22).encode(\x22utf-8\x22)
                    digest.update(relative.encode(\x22utf-8\x22))
                    digest.update(b\x22\0\x22)
                    digest.update(str(len(content)).encode(\x22ascii\x22))
                    digest.update(b\x22\0\x22)
                    digest.update(content)
    return \x22sha256:\x22 + digest.hexdigest()


def verified(root, expected, plugin):
    if not root.is_dir() or root.is_symlink() or digest_tree(root, plugin) != expected:
        fail(\x22Codex hook package integrity check failed\x22)


def main():
    root = Path(sys.argv[1])
    expected = sys.argv[2]
    plugin = sys.argv[3]
