            verified(temporary, expected, plugin)
            try:
                temporary.rename(snapshot)
            except OSError:
                if not snapshot.is_dir():
                    raise
        finally:
            if temporary.is_dir():
                shutil.rmtree(temporary)
    selected = snapshot
    verified(snapshot, expected, plugin)
    target = selected / relative
    if not target.is_file():
        fail(\x22Codex hook script is unavailable\x22)
    sys.path.insert(0, str(target.parent))
    sys.argv = [str(target), *(value.replace(str(root), str(selected), 1) for value in sys.argv[5:])]
    runpy.run_path(str(target), run_name=\x22__main__\x22)


if __name__ == \x22__main__\x22:
